diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..06b7b05
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,58 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { cook } from "../src/domain/recipes.js";
+import { app, fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+
+test("cooking bechamel takes soonest-expiring milk lot HD-1022 before HD-1026", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(res.status, 200);
+  const milkUsed = res.body.used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+});
+
+test("cooking spills over from HD-1022 into HD-1026 when more milk is needed", () => {
+  const store = fresh();
+  const used = cook(store, 2, 15, { at });
+  const milkUsed = used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed.batches, [
+    { batchId: 4, qty: 2 },
+    { batchId: 3, qty: 1 },
+  ]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 7);
+});
+
+test("consume follows FEFO: earliest expiry, no-expiry last, then receivedOn, then id", () => {
+  const store = fresh();
+  store.data.items.push({
+    id: 99,
+    sku: "DRY-TEST",
+    name: "salt",
+    unit: "kg",
+    minQty: 1,
+    supplierId: 1,
+    priceCents: 100,
+    tags: [],
+    allergens: [],
+  });
+  store.data.batches.push(
+    { id: 101, itemId: 99, lot: "NO-EXP-LATE", qty: 1, receivedOn: "2026-10-10", expires: null, location: "dry" },
+    { id: 102, itemId: 99, lot: "EXP-LATER", qty: 1, receivedOn: "2026-10-01", expires: "2026-11-10", location: "dry" },
+    { id: 105, itemId: 99, lot: "EXP-TIE-HIGH-ID", qty: 1, receivedOn: "2026-10-05", expires: "2026-11-01", location: "dry" },
+    { id: 103, itemId: 99, lot: "EXP-TIE-LOW-ID", qty: 1, receivedOn: "2026-10-05", expires: "2026-11-01", location: "dry" },
+    { id: 104, itemId: 99, lot: "EXP-TIE-EARLIER-RCV", qty: 1, receivedOn: "2026-10-02", expires: "2026-11-01", location: "dry" },
+    { id: 100, itemId: 99, lot: "NO-EXP-EARLY", qty: 1, receivedOn: "2026-10-01", expires: null, location: "dry" },
+  );
+
+  const used = consume(store, 99, 6, { at, ref: "test" });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [104, 103, 105, 102, 100, 101],
+  );
+});
